#!/bin/zsh
# Intro « Quinze ans plus tard » et écran titre (FLUX 3 Klein local, gratuit) -> work/intro/. Relançable : saute ce qui existe.
# Usage : gen_intro.sh [lot]   (a : décors, personnages de base, emblème, logos ; b : poses avec références)
cd "$(dirname "$0")/../work" && mkdir -p intro && cd intro || exit 1
SC="hand-painted cartoon 1990s PC adventure game background, VGA 256-color look with dithering, bold dark outlines, warm saturated colors, humorous storybook fantasy, no text, no people, no animals"
SP="full body game sprite, hand-painted 1990s PC point-and-click adventure game art, sarcastic cartoon style with realistic adult proportions, detailed painterly shading, bold dark outlines, saturated warm colors, plain flat solid magenta background, no shadow, no text"
PR="hand-painted 1990s PC point-and-click adventure game art, bold dark outlines, detailed painterly shading, saturated warm colors, plain flat solid magenta background, no shadow, no text"
g(){ out="$1"; shift; [ -f "$out" ] || flux-image "$@" -o "$out" >/dev/null 2>&1; echo "ok $out"; }
COMP="A burly blond Nordic warrior prisoner in his forties, long blond hair and beard in thick braids, a faded blue-gray padded cuirass with leather straps, fur over the shoulders, wrists tied in front with rope, friendly know-it-all smirk"
THIEF="A scrawny nervous bald Nordic thief in his thirties, tattered brown rags and a patched hood hanging on his back, thin pointy nose, big frightened eyes, stubble, wrists tied in front with rope"
lot=${1:-a}
if [[ $lot == a ]]; then
  for s in 11 12 13; do g p1_tall_$s.png "Tall vertical landscape painting of Skyrim at sunrise, composed in three bands from top to bottom: at the top a wide dawn sky with pink and gold clouds and faint green northern lights; in the middle the huge snowy peak of the Throat of the World mountain with a long stone staircase, flanked by smaller snowy mountains; at the bottom a deep green pine forest valley crossed horizontally by a winding dirt road, seen from slightly above. $SC" -s 1024x1152 --seed $s; done
  for s in 21 22 23; do g p2_pano_$s.png "Very wide panoramic side view of a Nordic countryside road in Skyrim on a golden morning, seen exactly from the side: a flat dirt road runs horizontally across the whole bottom of the picture, a grassy verge with blue mountain flowers and a few rocks, behind it rolling meadows, pine trees, a standing stone, a distant stone watchtower and snowy mountains on the horizon, big soft clouds. $SC" -s 1792x512 --seed $s; done
  for s in 31 32 33; do g comp_$s.png "$COMP, standing, seen from the front. $SP" -s 1024x1024 --seed $s; done
  for s in 41 42 43; do g thief_$s.png "$THIEF, standing, seen from the front. $SP" -s 1024x1024 --seed $s; done
  for s in 51 52 53; do g emblem_$s.png "A heraldic emblem engraved in brushed dark steel, like the dragon emblem of a fantasy game title screen: a wooden bucket shape with two long curved horns sprouting from its sides, embossed metal with subtle highlights, fine scratches and engraved Nordic knotwork, perfectly symmetric, centered, plain flat solid magenta background, no text" -s 1024x1024 --seed $s; done
  for s in 61 62 63; do g logo_fr_$s.png "Wide banner: the words \"LE SEAU DE RIVEBOIS\" written on one single line in large carved silver-gray capital letters with sharp serifs in an ancient Nordic style, chiseled brushed metal with soft highlights, centered, plain flat solid magenta background, nothing else" -s 1536x384 --seed $s; done
  for s in 71 72 73; do g logo_en_$s.png "Wide banner: the words \"THE BUCKET OF RIVERWOOD\" written on one single line in large carved silver-gray capital letters with sharp serifs in an ancient Nordic style, chiseled brushed metal with soft highlights, centered, plain flat solid magenta background, nothing else" -s 1536x384 --seed $s; done
  for s in 81 82; do g rail_$s.png "A long straight horizontal wooden side rail of an old prisoner cart seen from inside: two thick weathered horizontal planks held by three vertical posts with iron bolts, filling the width of the picture from edge to edge. $PR" -s 1792x384 --seed $s; done
  g prop_grass.png "A clump of tall wild grass with a few blue mountain flowers. $PR" -s 1024x1024 --seed 91
  g prop_rock.png "A gray mossy boulder. $PR" -s 1024x1024 --seed 92
  g prop_fence.png "A short section of an old weathered wooden fence, two posts and two rails, seen from the side. $PR" -s 1024x1024 --seed 93
  g prop_pine.png "A small young pine tree. $PR" -s 1024x1024 --seed 94
fi
if [[ $lot == t ]]; then   # pistes d'écran titre (ton comique et sarcastique de Simon the Sorcerer), héros en référence
  TS="Title screen illustration for a comedic 1990s point-and-click adventure game, hand-painted VGA pixel art in the spirit of Simon the Sorcerer, sarcastic humour, saturated colors, bold dark outlines, dithering, adult proportions. The hero is the man from the reference image: a smug young Nordic adventurer with a horned iron helmet, long auburn hair in a ponytail, fur collar, iron armor and a round wooden shield on his back, sly sarcastic grin."
  LOGO="a big golden carved title logo reading \"Le Seau de Rivebois\""
  for s in 101 102 103; do g title_A_$s.png "$TS At the top center, $LOGO on a weathered wooden sign. In the foreground on the left, the hero strikes a proud heroic pose, holding up an old wooden bucket like a sacred trophy in a ray of light. Behind him everything goes wrong: a dragon flies upside down in the sky, a giant in the distant meadow launches a mammoth into the sky with his club, a town guard sits on the ground clutching an arrow stuck in his knee, an angry chicken charges. Snowy mountains and a huge snowy peak, golden hour sky. The lower center of the picture stays fairly empty, a dirt road, room for a menu." -i ref_hero.png -s 1280x720 --seed $s; done
  for s in 111 112 113; do g title_B_$s.png "$TS At the top center, a cracked stone and rusty iron heraldic shield emblem: a startled chicken peeks over its top edge and an old wooden bucket sits in its center; across it $LOGO. On the left, the hero leans smugly against a barrel, eating a sticky honey roll, a hoarded pile of cabbages and cheese wheels at his feet. On the right, a town guard in chainmail and a yellow tabard sits in the snow pointing angrily at an arrow stuck in his knee, an overturned wooden cart behind him. Night, green northern lights, crescent moon, a dragon flying upside down, a small snowy Nordic village in the valley. The lower center stays fairly empty, a snowy path, room for a menu." -i ref_hero.png -s 1280x720 --seed $s; done
  for s in 121 122 123; do g title_C_$s.png "$TS Golden hour on the road to a Nordic village. At the top center, $LOGO hanging from chains under a wooden beam. A prisoner cart lies overturned in the middle of the road, one wheel in the air, its horse calmly eating grass. The hero sits on top of the overturned cart with a self-satisfied grin, eating a honey roll; next to the cart a burly blond Nordic prisoner with braided beard and a scrawny bald thief, still tied up with rope, glare at him. Snowy mountains, pine trees, a huge snowy peak. The lower center stays fairly empty, room for a menu." -i ref_hero.png -s 1280x720 --seed $s; done
  for s in 131 132 133; do g title_D_$s.png "$TS Painted 1990s fantasy movie poster composition in landscape format: at the top $LOGO; the hero stands in the center front raising an old wooden bucket, smug grin; behind and around him, stacked like a movie poster: a fat mustached merchant scowling, a bored town guard with an arrow in his knee, a dim-witted giant with a club, a cheerful farm woman with a pitchfork, a white chicken, a horse, and a huge dragon looming over everything wearing a small party hat. Dramatic sunset sky over snowy mountains." -i ref_hero.png -s 1280x720 --seed $s; done
fi
if [[ $lot == r ]]; then   # écran titre retenu : l'exemple de Stéphan (ref_example.jpg) refait avec nos personnages, en calques (décor sans texte + logo par langue)
  REF=(-i ref_example.jpg -i ref_hero.png -i ref_guard.png -i ref_hen.png)
  SCN="the composition, framing, lighting and colors of the first reference image: a snowy Nordic valley at night with green northern lights, stars and a crescent moon, a cracked stone and rusty iron heraldic shield emblem at the top center with a startled white chicken peeking over its top edge and an old wooden bucket on a rusty plate in its lower center, a small snowy village with warm lit windows in the valley, a small dragon flying, an overturned wooden cart on the right, snowy pine trees, in the same detailed hand-painted 1990s pixel-art style with dithering. Replace the grumpy bearded warrior sitting on the left with the hero from the second reference image: a smug young Nordic adventurer with a horned iron helmet, long auburn hair in a ponytail, fur collar, iron armor, a round wooden shield on his back and a sly sarcastic grin; he sits on a crate next to barrels, hugging a green cabbage and a big wheel of yellow cheese. Replace the guard sitting in the snow on the right with the town guard from the third reference image: steel helmet with cheek guards, yellow-brown tabard over chainmail; he sits in the snow pointing angrily, an arrow stuck in his knee. The chicken on the emblem is the white chicken from the fourth reference image."
  for s in 201 202 203 204; do g tbg_$s.png "Recreate $SCN Absolutely no text, no letters, no title anywhere: the area across the middle of the emblem stays free for a title added later." $REF -s 1280x720 --seed $s; done
  for s in 211 212; do g tfull_$s.png "Recreate $SCN Across the emblem, the same big golden medieval title \"Le Seau de Rivebois\" and below it the same subtitle \"1 000 quêtes. 0 place dans l'inventaire.\" as in the first reference image." $REF -s 1280x720 --seed $s; done
  LG="in big bold golden blackletter-style medieval letters with a dark brown outline and a soft bevel, exactly like the title of the reference image; below it, smaller and centered, the line"
  for s in 221 222 223; do g tlogo_fr_$s.png "The words \"Le Seau de Rivebois\" $LG \"1 000 quêtes. 0 place dans l'inventaire.\" in bold golden sans-serif letters with a dark outline, like the subtitle of the reference image. Centered on a plain flat solid magenta background, nothing else." -i ref_example.jpg -s 1536x512 --seed $s; done
  for s in 231 232 233; do g tlogo_en_$s.png "The words \"The Bucket of Riverwood\" $LG \"1,000 quests. 0 inventory space.\" in bold golden sans-serif letters with a dark outline, like the subtitle of the reference image. Centered on a plain flat solid magenta background, nothing else." -i ref_example.jpg -s 1536x512 --seed $s; done
fi
if [[ $lot == b ]]; then   # charrette (image de départ du cycle de pas), compagnon de dos (amorce), voleur en buste (4-5 poses)
  for s in 301 302 303; do g cart_side_$s.png "A horse-drawn wooden prisoner cart seen exactly from the side, pure profile, moving to the right: a sturdy brown horse in harness walking in front, pulling the cart; a grumpy old coachman in a fur hat and a brown cloak sits on the front bench holding the reins; the cart bed behind him is EMPTY, with low plank side rails and two big spoked wooden wheels. The whole horse and cart are visible with a margin all around. $SP" -s 1344x768 --seed $s; done
  CB="The same man as in the reference image, same blond braids, same fur over the shoulders, same faded blue-gray cuirass, same art style, seen from behind: a close-up of the back of his head, his right shoulder and upper back, as if he sat in the foreground with his back to the viewer, cut at the chest. Plain flat solid magenta background, no shadow, no text."
  i=0; for p in "His head is straight." "His head is turned slightly to the right, we glimpse his cheek and the edge of his beard." "His head is tilted to the side, as if nodding while talking." "He shrugs his shoulder, head turned slightly to the right."; do i=$((i+1)); for s in 311 312; do g comp_back${i}_$s.png "$CB $p" -i comp_32.png -s 1024x1024 --seed $s; done; done
  TB="The same man as in the reference image, same bald head, same face, same tattered brown rags and rope-tied wrists, same art style and colors, bust portrait framing showing his head, shoulders and chest, facing the viewer. Plain flat solid magenta background, no shadow, no text."
  i=0; for p in "He shouts in panic, mouth wide open, eyes huge." "He raises his tied hands in front of his chest, pleading, eyebrows raised." "He clutches his bald head with his tied hands, horrified." "He points at his own chest with both tied hands, indignant, mouth open." "He whimpers, lower lip trembling, eyes wet."; do i=$((i+1)); for s in 321 322; do g thief_cu${i}_$s.png "$TB $p" -i thief_42.png -s 1024x1024 --seed $s; done; done
fi
echo "lot $lot fini"
